Here is the commit message:
button: qcom-pmic: fix some error checking

The pmic_reg_read() function can return errors.  Add a check for that.

Fixes: 4e8aa0065d4b ("button: qcom-pmic: introduce Qualcomm PMIC button driver")
Signed-off-by: Dan Carpenter <dan.carpenter@linaro.org>
Reviewed-by: Caleb Connolly <caleb.connolly@linaro.org>
Reviewed-by: Sumit Garg <sumit.garg@linaro.org>

Here is the root cause:
The bug arises from inadequate error checking in the `pmic_reg_read()` function, which can return negative values indicating an error. The original code only checked if the returned value was zero or not, potentially leading to misinterpretation of error states as valid data, which could cause unexpected behavior in the driver.

Here is the patch:

 static int qcom_pwrkey_probe(struct udevice *dev)
 {
 	struct button_uc_plat *uc_plat = dev_get_uclass_plat(dev);
 	struct qcom_pmic_btn_priv *priv = dev_get_priv(dev);
 	ofnode node = dev_ofnode(dev);
 	int ret;
 	u64 base;

 	/* Ignore the top-level pon node */
 	if (!uc_plat->label)
 		return 0;

 	/* the pwrkey and resin nodes are children of the "pon" node, get the
 	 * PMIC device to use in pmic_reg_* calls.
 	 */
 	priv->pmic = dev->parent->parent;

 	/* Get the address of the parent pon node */
 	base = dev_read_addr(dev->parent);
 	if (base == FDT_ADDR_T_NONE) {
 		printf("%s: Can't find address\n", dev->name);
 		return -EINVAL;
 	}

 	priv->base = base;

 	/* Do a sanity check */
 	ret = pmic_reg_read(priv->pmic, priv->base + REG_TYPE);
 	if (ret != 0x1 && ret != 0xb) {
 		printf("%s: unexpected PMIC function type %d\n", dev->name, ret);
 		return -ENXIO;
 	}

 	ret = pmic_reg_read(priv->pmic, priv->base + REG_SUBTYPE);
-	if ((ret & 0x7) == 0) {
+	if (ret < 0 || (ret & 0x7) == 0) {
 		printf("%s: unexpected PMCI function subtype %d\n", dev->name, ret);
 		return -ENXIO;
 	}

 	if (NODE_IS_PWRKEY(node)) {
 		priv->status_bit = 0;
 		priv->code = KEY_ENTER;
 	} else if (NODE_IS_RESIN(node)) {
 		priv->status_bit = 1;
 		priv->code = KEY_DOWN;
 	} else {
 		/* Should not get here! */
 		printf("Invalid pon node '%s' should be 'pwrkey' or 'resin'\n",
 		       ofnode_get_name(node));
 		return -EINVAL;
 	}

 	return 0;
 }



